fn tally(xs: List[Int], x: Int) -> Int
  requires len(xs) >= 0
  ensures result == count(xs, x)
  effects pure
  example tally([1, 2, 2, 3], 2) == 2
  example tally([], 5) == 0
  example tally([4, 4, 4], 4) == 3
{
  match xs {
    [] => 0
    [h, ..t] => if h == x then 1 + tally(t, x) else tally(t, x)
  }
}

fn is_max(xs: List[Int], whole: List[Int], m: Int) -> Bool
  requires len(whole) >= len(xs)
  ensures result or exists x in xs: count(whole, x) > count(whole, m)
  effects pure
  example is_max([1, 2, 2, 3], [1, 2, 2, 3], 2) == true
  example is_max([1, 2, 2, 3], [1, 2, 2, 3], 1) == false
  example is_max([], [1], 1) == true
{
  match xs {
    [] => true
    [h, ..t] => tally(whole, m) >= tally(whole, h) and is_max(t, whole, m)
  }
}

fn best_in(xs: List[Int], whole: List[Int], r: Option[Int]) -> Bool
  requires len(xs) <= len(whole)
  ensures result or len(xs) > 0
  effects pure
  example best_in([1, 2, 2, 3], [1, 2, 2, 3], Some(2)) == true
  example best_in([1, 2, 2, 3], [1, 2, 2, 3], Some(1)) == false
  example best_in([], [], None) == true
  example best_in([1], [1], None) == false
{
  match r {
    None => match xs {
      [] => true
      [_, ..t] => false
    }
    Some(m) => is_max(xs, whole, m)
  }
}

fn pick(xs: List[Int], whole: List[Int]) -> Option[Int]
  requires len(xs) <= len(whole)
  ensures best_in(xs, whole, result)
  ensures (len(xs) == 0) == (result == None)
  effects pure
  example pick([1, 2, 2, 3], [1, 2, 2, 3]) == Some(2)
  example pick([], [1]) == None
  example pick([5, 7, 7], [5, 7, 7]) == Some(7)
{
  match xs {
    [] => None
    [h, ..t] => match pick(t, whole) {
      None => Some(h)
      Some(b) => if tally(whole, h) > tally(whole, b) then Some(h) else Some(b)
    }
  }
}

fn most_frequent(xs: List[Int]) -> Option[Int]
  requires len(xs) == 0 or exists m in xs: forall x in xs: x == m or count(xs, x) < count(xs, m)
  ensures best_in(xs, xs, result)
  ensures (len(xs) == 0) == (result == None)
  effects pure
  example most_frequent([1, 2, 2, 3]) == Some(2)
  example most_frequent([]) == None
  example most_frequent([7, 1, 7, 7, 4, 4]) == Some(7)
{
  pick(xs, xs)
}

