fn max_opt(xs: List[Int]) -> Option[Int]
  requires len(xs) >= 0
  ensures (len(xs) == 0) == (result == None)
  effects pure
  example max_opt([]) == None
  example max_opt([3, 9, 1]) == Some(9)
  example max_opt([4]) == Some(4)
{
  match xs {
    [] => None
    [h, ..t] => match max_opt(t) {
      None => Some(h)
      Some(m) => if h > m then Some(h) else Some(m)
    }
  }
}

fn below(xs: List[Int], m: Int) -> List[Int]
  requires len(xs) >= 0
  ensures forall x in result: x < m
  ensures forall x in xs: not (x < m) or contains(result, x)
  effects pure
  example below([3, 9, 1], 9) == [3, 1]
  example below([4], 4) == []
  example below([], 0) == []
{
  match xs {
    [] => []
    [h, ..t] => if h < m then [h] ++ below(t, m) else below(t, m)
  }
}

fn second_largest(xs: List[Int]) -> Option[Int]
  requires distinct(xs)
  ensures (len(xs) < 2) == (result == None)
  effects pure
  example second_largest([3, 9, 1]) == Some(3)
  example second_largest([4]) == None
  example second_largest([]) == None
  example second_largest([1, 2]) == Some(1)
  example second_largest([5, 10, 7]) == Some(7)
{
  match max_opt(xs) {
    None => None
    Some(m) => max_opt(below(xs, m))
  }
}

